diff --git a/tools/jev_call.mjs b/tools/jev_call.mjs
new file mode 100644
index 0000000..5e0b4bf
--- /dev/null
+++ b/tools/jev_call.mjs
@@ -0,0 +1,185 @@
+#!/usr/bin/env node
+// Call real Jev MCP tools (@jkudish/jev-mcp over stdio) and keep an immutable receipt per call.
+//
+//   node tools/jev_call.mjs --run RUN_DIR --id DECISION_ID --tool jev_decide --args args.json [--purpose "..."] [--evidence-file path ...]
+//
+// RUN_DIR is created if missing; each call writes RUN_DIR/<id>.json holding the exact request, the full
+// MCP result, SHA-256 of every named evidence file, wall time, and server/model identity. An existing
+// receipt is never overwritten. API keys are read from the environment, redacted from anything the
+// recorder stores, and never written. Arguments are validated before any file is created; a failing
+// server or a malformed reply still produces a receipt that says what went wrong.
+//
+// Test hooks: --server runs a JS file with node instead of the package; --command replaces npx.
+import { spawn } from "node:child_process";
+import { createHash } from "node:crypto";
+import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
+import { join, resolve } from "node:path";
+import { parseArgs } from "node:util";
+
+const PACKAGE = `@jkudish/jev-mcp@${process.env.JEV_MCP_VERSION ?? "0.13.0"}`;
+
+function usage(message) {
+  console.error(message);
+  process.exit(2);
+}
+
+let values;
+try {
+  ({ values } = parseArgs({
+    options: {
+      run: { type: "string" },
+      id: { type: "string" },
+      tool: { type: "string" },
+      args: { type: "string" },
+      purpose: { type: "string", default: "" },
+      "evidence-file": { type: "string", multiple: true, default: [] },
+      server: { type: "string", default: process.env.JEV_MCP_BIN ?? "" },
+      command: { type: "string", default: "" },
+      timeout: { type: "string", default: "180000" },
+    },
+  }));
+} catch (error) {
+  usage(String(error.message ?? error));
+}
+for (const key of ["run", "id", "tool", "args"]) {
+  if (!values[key]) usage(`missing --${key}`);
+}
+if (!/^[A-Za-z0-9._-]+$/.test(values.id)) usage("--id must be a stable slug");
+const timeoutMs = Number(values.timeout);
+if (!Number.isFinite(timeoutMs) || timeoutMs <= 0 || timeoutMs > 2 ** 31 - 1) usage("--timeout must be between 1 and 2147483647 milliseconds");
+
+const sha256 = (buffer) => createHash("sha256").update(buffer).digest("hex");
+function readOrExit(path, what) {
+  try {
+    return readFileSync(path);
+  } catch (error) {
+    return usage(`cannot read ${what} ${path}: ${error.code ?? error.message}`);
+  }
+}
+const argsBytes = readOrExit(values.args, "--args");
+let toolArgs;
+try {
+  toolArgs = JSON.parse(argsBytes.toString("utf8"));
+} catch (error) {
+  usage(`--args is not valid JSON: ${error.message}`);
+}
+const evidenceFiles = values["evidence-file"].map((path) => {
+  const bytes = readOrExit(path, "--evidence-file");
+  return { path, sha256: sha256(bytes), bytes: bytes.length };
+});
+
+const runDir = resolve(values.run);
+const receiptPath = join(runDir, `${values.id}.json`);
+if (existsSync(receiptPath)) usage(`receipt exists, not overwriting: ${receiptPath}`);
+mkdirSync(runDir, { recursive: true });
+
+// Literal key values are redacted wherever recorder-controlled text is stored.
+const secrets = ["OPENROUTER_API_KEY", "TYPESAFE_API_KEY"].map((name) => process.env[name]).filter((value) => value && value.length >= 8);
+const redact = (text) => secrets.reduce((out, secret) => out.split(secret).join("[redacted]"), String(text)).replace(/sk-or-[A-Za-z0-9_-]+/g, "[redacted]");
+
+const command = values.command || (values.server ? process.execPath : "npx");
+const serverArgs = values.server ? [values.server] : ["-y", PACKAGE];
+const env = { ...process.env, JEV_MCP_MODEL: process.env.JEV_MCP_MODEL ?? "typesafe/jev-1.13" };
+
+const nonJsonLines = [];
+const pending = new Map();
+let stderr = "";
+let buffer = "";
+let nextId = 1;
+let childFailure = null;
+
+function failPending(reason) {
+  childFailure ??= reason;
+  for (const [id, entry] of pending) {
+    clearTimeout(entry.timer);
+    entry.reject(new Error(reason));
+    pending.delete(id);
+  }
+}
+
+const child = spawn(command, serverArgs, { env, stdio: ["pipe", "pipe", "pipe"] });
+child.on("error", (error) => failPending(`could not run the server (${command}): ${error.code ?? error.message}`));
+// "close" fires after the stdio streams have ended, so a reply written just before exit is already handled.
+child.on("close", (code, signal) => failPending(`server exited before replying (code ${code}, signal ${signal})`));
+child.stdin.on("error", () => {}); // a dead server is reported through the exit/error handlers
+child.stderr.setEncoding("utf8");
+child.stderr.on("data", (chunk) => (stderr += chunk));
+child.stdout.setEncoding("utf8"); // decode once so multibyte characters split across chunks stay intact
+child.stdout.on("data", (chunk) => {
+  buffer += chunk;
+  let newline;
+  while ((newline = buffer.indexOf("\n")) >= 0) {
+    const line = buffer.slice(0, newline).trim();
+    buffer = buffer.slice(newline + 1);
+    if (!line) continue;
+    let message;
+    try {
+      message = JSON.parse(line);
+    } catch {
+      nonJsonLines.push(redact(line).slice(0, 200));
+      continue;
+    }
+    if (message.id !== undefined && pending.has(message.id)) {
+      const entry = pending.get(message.id);
+      clearTimeout(entry.timer);
+      pending.delete(message.id);
+      entry.resolve(message);
+    }
+  }
+});
+
+const rpc = (method, params) =>
+  new Promise((resolvePromise, reject) => {
+    if (childFailure) return reject(new Error(childFailure));
+    const id = nextId++;
+    const timer = setTimeout(() => {
+      pending.delete(id);
+      reject(new Error(`timeout on ${method}`));
+    }, timeoutMs);
+    pending.set(id, { resolve: resolvePromise, reject, timer });
+    child.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
+  });
+
+const started = Date.now();
+const base = {
+  id: values.id,
+  purpose: values.purpose,
+  tool: values.tool,
+  server_package: values.server ? `local:${values.server}` : PACKAGE,
+  arguments: toolArgs,
+  args_file: values.args,
+  args_sha256: sha256(argsBytes),
+  evidence_files: evidenceFiles,
+  started_utc: new Date(started).toISOString(),
+};
+let receipt;
+try {
+  const init = await rpc("initialize", { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "fr2-jev-ledger", version: "1" } });
+  child.stdin.write(JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }) + "\n");
+  const call = await rpc("tools/call", { name: values.tool, arguments: toolArgs });
+  receipt = {
+    ...base,
+    server: init.result?.serverInfo ?? null,
+    model: env.JEV_MCP_MODEL,
+    provider_env: env.TYPESAFE_API_KEY ? "typesafe" : env.OPENROUTER_API_KEY ? "openrouter" : "none",
+    seconds: (Date.now() - started) / 1000,
+    rpc_error: call.error ?? null,
+    is_error: call.result?.isError ?? false,
+    non_json_stdout_lines: nonJsonLines,
+    result: call.result ?? null,
+  };
+} catch (error) {
+  receipt = {
+    ...base,
+    seconds: (Date.now() - started) / 1000,
+    operational_failure: redact(error.message ?? error),
+    non_json_stdout_lines: nonJsonLines,
+    stderr_tail: redact(stderr.slice(-2000)),
+  };
+} finally {
+  child.kill();
+}
+writeFileSync(receiptPath, JSON.stringify(receipt, null, 2) + "\n", { flag: "wx" });
+const text = receipt.result?.content?.map((part) => part.text).join("\n") ?? JSON.stringify(receipt.operational_failure ?? receipt.rpc_error);
+console.log(text);
+process.exit(receipt.operational_failure || receipt.is_error || receipt.rpc_error ? 1 : 0);

diff --git a/tools/jev_call.test.mjs b/tools/jev_call.test.mjs
new file mode 100644
index 0000000..ee05d5f
--- /dev/null
+++ b/tools/jev_call.test.mjs
@@ -0,0 +1,122 @@
+// node --test tools/jev_call.test.mjs
+// Runs the receipt recorder against a fake MCP server; no network and no real key are used.
+import assert from "node:assert/strict";
+import { spawnSync } from "node:child_process";
+import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { dirname, join } from "node:path";
+import { test } from "node:test";
+import { fileURLToPath } from "node:url";
+
+const here = dirname(fileURLToPath(import.meta.url));
+const recorder = join(here, "jev_call.mjs");
+
+function workspace(fakeBody) {
+  const dir = mkdtempSync(join(tmpdir(), "jevcall-"));
+  const server = join(dir, "fake-server.mjs");
+  writeFileSync(
+    server,
+    `import { createInterface } from "node:readline";
+const rl = createInterface({ input: process.stdin });
+rl.on("line", (line) => {
+  const message = JSON.parse(line);
+  if (message.method === "initialize") reply(message.id, { serverInfo: { name: "fake", version: "9.9.9" } });
+  if (message.method === "tools/call") { ${fakeBody} }
+});
+function reply(id, result) { process.stdout.write(JSON.stringify({ jsonrpc: "2.0", id, result }) + "\\n"); }
+`,
+  );
+  const args = join(dir, "args.json");
+  writeFileSync(args, JSON.stringify({ text: "x" }));
+  return { dir, server, args, run: join(dir, "run") };
+}
+
+function record(ws, extra = [], env = {}) {
+  return spawnSync(
+    process.execPath,
+    [recorder, "--run", ws.run, "--id", "r1", "--tool", "jev_screen", "--args", ws.args, "--server", ws.server, ...extra],
+    { env: { ...process.env, ...env }, encoding: "utf8" },
+  );
+}
+const receipt = (ws) => JSON.parse(readFileSync(join(ws.run, "r1.json"), "utf8"));
+
+test("multibyte text split across stdout chunks is preserved exactly", () => {
+  const ws = workspace(`reply(message.id, { content: [{ type: "text", text: "€😀".repeat(40000) }] });`);
+  const done = record(ws);
+  assert.equal(done.status, 0, done.stderr);
+  assert.equal(receipt(ws).result.content[0].text, "€😀".repeat(40000));
+});
+
+test("a non-JSON stdout line does not lose the receipt and is recorded", () => {
+  const ws = workspace(`process.stdout.write("warning: not json\\n"); reply(message.id, { content: [{ type: "text", text: "ok" }] });`);
+  const done = record(ws);
+  assert.equal(done.status, 0, done.stderr);
+  const r = receipt(ws);
+  assert.equal(r.result.content[0].text, "ok");
+  assert.deepEqual(r.non_json_stdout_lines, ["warning: not json"]);
+});
+
+test("a missing server command is recorded as an operational failure, not a stack trace", () => {
+  const ws = workspace(`reply(message.id, {});`);
+  const done = record(ws, ["--command", join(ws.dir, "no-such-binary")]);
+  assert.equal(done.status, 1);
+  assert.doesNotMatch(done.stderr, /at .*node:internal/);
+  assert.match(receipt(ws).operational_failure, /ENOENT|no-such-binary|spawn/);
+});
+
+test("key values are redacted from the recorded stderr tail", () => {
+  const key = "sk-test-SECRET-0123456789";
+  const ws = workspace(`process.stderr.write("auth failed for ${key}\\n"); process.exit(3);`);
+  const done = record(ws, [], { OPENROUTER_API_KEY: key, TYPESAFE_API_KEY: "tsk_plain_value_98765" });
+  assert.equal(done.status, 1);
+  const text = readFileSync(join(ws.run, "r1.json"), "utf8");
+  assert.doesNotMatch(text, /SECRET-0123456789/);
+  assert.match(text, /\[redacted\]/);
+});
+
+test("bad arguments exit 2 before any file is created", () => {
+  const ws = workspace(`reply(message.id, {});`);
+  for (const extra of [["--timeout", "abc"], ["--evidence-file", join(ws.dir, "missing.txt")]]) {
+    const done = record(ws, extra);
+    assert.equal(done.status, 2, `${extra}: ${done.stderr}`);
+    assert.doesNotMatch(done.stderr, /at .*node:internal/);
+    assert.equal(existsSync(ws.run), false, `${extra} created the run directory`);
+  }
+});
+
+test("an existing receipt is never overwritten", () => {
+  const ws = workspace(`reply(message.id, { content: [{ type: "text", text: "first" }] });`);
+  assert.equal(record(ws).status, 0);
+  const before = readFileSync(join(ws.run, "r1.json"), "utf8");
+  const again = record(ws);
+  assert.equal(again.status, 2);
+  assert.equal(readFileSync(join(ws.run, "r1.json"), "utf8"), before);
+});
+
+test("a server that flushes its reply and then exits still yields the reply", () => {
+  const ws = workspace(`process.stdout.write(JSON.stringify({ jsonrpc: "2.0", id: message.id, result: { content: [{ type: "text", text: "x".repeat(200000) }] } }) + "\\n", () => process.exit(0));`);
+  for (let attempt = 0; attempt < 5; attempt++) {
+    const dir = ws.run + attempt;
+    const done = spawnSync(process.execPath, [recorder, "--run", dir, "--id", "r1", "--tool", "jev_screen", "--args", ws.args, "--server", ws.server], { encoding: "utf8" });
+    assert.equal(done.status, 0, done.stderr);
+    const r = JSON.parse(readFileSync(join(dir, "r1.json"), "utf8"));
+    assert.equal(r.operational_failure, undefined);
+    assert.equal(r.result.content[0].text.length, 200000);
+  }
+});
+
+test("an oversized timeout is rejected instead of firing immediately", () => {
+  const ws = workspace(`reply(message.id, {});`);
+  const done = record(ws, ["--timeout", "3000000000"]);
+  assert.equal(done.status, 2, done.stderr);
+  assert.equal(existsSync(ws.run), false);
+});
+
+test("a key split by the 200-character cut is still redacted", () => {
+  const key = "sk-test-SECRET-0123456789";
+  const ws = workspace(`process.stdout.write("a".repeat(180) + "${key}" + "\\n"); reply(message.id, { content: [{ type: "text", text: "ok" }] });`);
+  const done = record(ws, [], { OPENROUTER_API_KEY: key });
+  assert.equal(done.status, 0, done.stderr);
+  const text = readFileSync(join(ws.run, "r1.json"), "utf8");
+  assert.doesNotMatch(text, /SECRE/);
+});

